{"implementation":"def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])
    node_map = {n['id']: n for n in nodes}
    children = {n['id']: [] for n in nodes}
    for n in nodes:
        p = n.get('parent')
        if p:
            children[p].append(n['id'])
    retained = {n['id'] for n in nodes}
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    removed = []
    for n in sorted_nodes:
        if not n['removable']:
            continue
        if n['symbol'] in required_symbols:
            continue
        if any(c in retained for c in children[n['id']]):
            continue
        retained.discard(n['id'])
        if all(any(m['symbol'] == sym for m in nodes if m['id'] in retained) for sym in required_symbols):
            removed.append(n['id'])
        else:
            retained.add(n['id'])
    return {'removed_node_ids': removed, 'retained_node_ids': sorted(retained)}
"}
